Suppose Assumptions E.1, E.2, E.3, E.4, and E.5 hold. Let $0<\alpha < 1/2$.
\begin{enumerate}[label=(\Roman*)]
\item  Let $CI_n$ be as defined in (1.4), with $\hat{c}_n$ as in (2.13). Then:
\begin{align}
\liminf_{n\to\infty}\inf_{P\in\mathcal P}\inf_{\theta\in\Theta_I(P)}P(p'\theta\in CI_n)\ge 1-\alpha.
\end{align}
\item  Let $p^1,\dots,p^h$ denote unit vectors in $\mathbb{R}^d$, $h \le d$. Then:\begin{align}
\liminf_{n\to\infty}\inf_{P\in\mathcal P}\inf_{\theta\in\Theta_I(P)}P(p^{k \prime}\theta \in CI_{n,k},k=1,\dots,h)\ge 1-\alpha,
\end{align}
where $CI_{n,k}=\left[\inf_{\theta\in\mathcal C_n(\hat{c}^h_n)} p^{k \prime}\theta, \sup_{\theta\in\mathcal C_n(\hat{c}^h_n)} p^{k \prime }\theta \right]$ and $\hat c^h_n(\theta)\equiv \inf\{c\in\mathbb R_+:P^*(\Lambda_n^b (\theta ,\rho ,c)\cap \{\cap_{k=1}^h\{p^{k \prime }\lambda =0\}\}\neq \emptyset)\ge 1-\alpha\}$.
\item 	 Let $CI_n^f$ be a confidence interval whose lower and upper points are obtained solving
\begin{align*}
\inf_{\theta \in \Theta} / \sup_{\theta \in \Theta} f(\theta) \text{  s.t. }\sqrt{n}\bar{m}_{n,j}(\theta )/\hat{\sigma}_{n,j}(\theta )\leq
\hat{c}^f_n(\theta),~j=1,... ,J,
\end{align*}
where $\hat c^f_n(\theta)\equiv \inf\{c \geq 0:P^*(\Lambda_n^b (\theta ,\rho ,c)\cap \{\|\nabla_\theta f(\theta )\|^{-1}\nabla_\theta f(\theta )\lambda =0\}\neq \emptyset)\ge 1-\alpha\}$.
Suppose that there exist $\varpi>0$ and $M<\infty$ such that $\inf_{P\in\mathcal P}\inf_{\theta\in\Theta_I(P)}\Vert \nabla f(\theta)\Vert\ge \varpi$ and $\sup_{\theta,\bar{\theta}\in\Theta}\Vert \nabla f(\theta)-\nabla f(\bar{\theta})\Vert\le M \Vert \theta -\bar{\theta} \Vert$, where $\nabla_\theta f(\theta)$ is the gradient of $f(\theta)$.\footnote{Because the function $f$ is known, these conditions can be easily verified in practice (especially if the first one is strengthened to hold over $\Theta$).} Let $0<\alpha < 1/2$. Then:
\begin{align}
\liminf_{n\to\infty}\inf_{P\in\mathcal P}\inf_{\theta\in\Theta_I(P)}P(f(\theta)\in CI_n^f)\ge 1-\alpha.
\end{align}
\end{enumerate}

Suppose Assumptions E.1, E.2,  E.3, E.4, and E.5 hold.
Let	$\{P_n,\theta_n\} \in \{(P,\theta):P \in \mathcal{P},\theta \in \Theta_I(P)\}$ be a sequence satisfying (H.1)-(H.3). 
For each $j$, let
\begin{align}
v^I_{n,j,\theta_n}(\lambda)&\equiv	\mathbb G^b_{n,j}(\theta_n)+\rho\hat{D}_{n,j}(\theta_n)\lambda+\varphi^*_j(\hat{\xi}_{n,j}(\theta_n)),\\
\mathfrak{w}_{j}(\lambda)&\equiv \mathbb{Z}_{j}+\rho D_{j}\lambda+\pi^*_{1,j},
\end{align}
where 
\begin{align}
\varphi^*_j(\xi)=\begin{cases}
	\varphi_j(\xi)&\pi_{1,j}=0\\
	-\infty&\pi_{1,j}<0\\
	0&j=J_1+1,\cdots,J.
\end{cases}	
\end{align}
For each $c\ge0$, define
\begin{align}
V^I_n(\theta_n,c)&\equiv \{\lambda\in B^d_{n,\rho}:p'\lambda=0\cap v^I_{n,j,\theta_n}(\lambda)\le c,j=1,\cdots,J\},\\
\mathfrak{W}(c)&\equiv \big\{ \lambda\in \mathfrak B^d_\rho: p^\prime \lambda = 0 \cap \mathfrak w_{j}(\lambda)\le c, \: \forall j=1,\dots,J\big\}.
\end{align}
We then let $c^I_n(\theta_n)\equiv \inf\{c\in\mathbb{R}_+:P^*_n(V^I_n(\theta_n,c)\neq \emptyset)\ge 1-\alpha\}$ and $c_{\pi^*}\equiv \inf\{c\in\mathbb R_+:\Pr(\mathfrak{W}(c)\ne\emptyset)\ge 1-\alpha\}$.

Then, 
(i) for any $c>0$ and $\{\theta'_n\}\subset\Theta$ such that $\theta'_n\in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$ for all $n$, 
\begin{align}
P^*_n(V^I_n(\theta'_n,c)\ne\emptyset)-	\Pr(\mathfrak{W}(c)\ne\emptyset)\to 0,
\end{align}	
with probability approaching 1; 

\noindent
(ii)  If $c_{\pi^*}>0$, $c^I_n(\theta'_n)\stackrel{P_n}{\to}c_{\pi^*};$ 

\noindent
(iii) For any $\{\theta'_n\}\subset\Theta$ such that $\theta'_n\in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$ for all $n$,
\begin{align}
\hat c_n(\theta'_n)\ge c^I_n(\theta'_n)+o_{P_n}(1).	
\end{align}

Let Assumptions E.1, E.2, E.4, and E.5 hold. 

Given a sequence $\{Q_n,\vartheta_n\} \in \{(P,\theta):P \in \mathcal{P},\theta \in \Theta_I(P)\}$ such that $\lim_{n \to \infty} \kappa_n^{-1}\sqrt{n}\gamma_{1,Q_n,j}(\vartheta_n)$ exists for each $j=1,\dots,J$, let $\chi_j(\{Q_n,\vartheta_n\})$ be a function of the sequence $\{Q_n,\vartheta_n\}$ defined as
\begin{align}

\chi_j(\{Q_n,\vartheta_n\}) \equiv \left\{ \begin{array}{ll}
	0, & \mathrm{if}~ \lim_{n \to \infty} \kappa_n^{-1}\sqrt{n}\gamma_{1,Q_n,j}(\vartheta_n) = 0, \\ 
	-\infty, & \mathrm{if}~ \lim_{n \to \infty} \kappa_n^{-1}\sqrt{n}\gamma_{1,Q_n,j}(\vartheta_n) < 0.
	\end{array} 
	\right. 
\end{align} 
Then for any $\theta^\prime_n \in \theta_n +\frac{\rho }{\sqrt n}B^d$ for all $n$, one has:  (i) $\kappa_n^{-1}\sqrt{n}\gamma_{1,P_n,j}(\theta_n)-\kappa_n^{-1}\sqrt{n}\gamma_{1,P_n,j}(\theta_n^\prime) =o(1)$; (ii) $\chi(\{P_n,\theta_n\})=\chi(\{P_n,\theta_n^\prime\})=\pi^*_{1,j}$; and (iii) $\kappa_n^{-1}\frac{\sqrt n \bar{m}_{n,j}(\theta^\prime_{n})}{\hat{\sigma}_{n,j}(\theta^\prime_{n})}-\kappa_n^{-1}\frac{\sqrt nE_{P_n}[m_j(X_i,\theta^\prime_{n})]}{\sigma_{P_n,j}(\theta^\prime_{n})} =o_{\mathcal{P}}(1)$.
}

Let Assumptions E.1, E.2, E.3, E.4, and E.5 hold.  
	 For any $\theta_n^\prime \in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$,
	\begin{itemize}
	\item[(i)]
For any $\eta>0$, there exist $\delta>0$   such that
	\begin{align}
		\sup_{c \ge 0}\Pr(\{\mathfrak W(c)\ne\emptyset\}\cap \{\mathfrak W^{-\delta}(c)=\emptyset\})<\eta.
		\end{align}
Moreover, for any $\eta>0$, there exist $\delta>0$ and $N\in\mathbb N$  such that
	\begin{align}
		\sup_{c \ge 0}P_n^*(\{V^I_n(\theta_n^\prime,c)\ne\emptyset\}\cap \{V_n^{I,-\delta}(\theta_n^\prime,c)=\emptyset\})<\eta,~\forall n\ge N.
		\end{align}
	\item[(ii)] Fix $\underline{c}>0$ and redefine
	\begin{align}
\mathfrak W^{-\delta}(c)
\equiv \big\{ \lambda\in \mathfrak B^d_\rho: p^\prime \lambda =0 &\cap \mathfrak w_j(\lambda)\le c-\delta , \: \forall j=1,\dots,J\big\}, 
	\end{align}
and
	\begin{align}
V_n^{I,-\delta}(\theta_n^\prime,c)
\equiv \big\{ \lambda\in B^d_{n,\rho}: p^\prime \lambda =0 &\cap v^I_{n,j,\theta_n^\prime}(\lambda)\le c-\delta, \: \forall j=1,\dots,J\big\}. 
	\end{align}
	Then for any $\eta>0$, there exists $\delta>0$   such that
	\begin{align}
		\sup_{c \ge \underline{c}}\Pr(\{\mathfrak W(c)\ne\emptyset\}\cap \{\mathfrak W^{-\delta}(c)=\emptyset\})<\eta.
		\end{align}
		with $\mathfrak W^{-\delta}(c)$ defined in (H.137).
Moreover, for any $\eta>0$, there exist $\delta>0$ and $N\in\mathbb N$  such that
	\begin{align}
		\sup_{c \ge \underline{c}}P_n^*(\{V^I_n(\theta_n^\prime,c)\ne\emptyset\}\cap \{V_n^{I,-\delta}(\theta_n^\prime,c)=\emptyset\})<\eta,~\forall n\ge N,
		\end{align}
		with $V_n^{-\delta }(\theta_n^\prime,c)$ defined in (H.138).
\end{itemize}

Let Assumptions E.1, E.2, E.3, E.4, and E.5 hold.  If $J_2 \ge d$, then $\exists \underline{c} >0$ s.t.
\begin{align*}
\liminf_{n \to\infty}\inf_{P\in\mathcal P}\inf_{\theta\in \Theta_I(P)}P(c^I_{n}(\theta)\ge \underline c)=1.  
\end{align*}

Suppose Assumptions E.1, E.2, and E.5 hold. For each $\theta\in\Theta$, let $\eta_{n,j}(\theta)=\sigma_{P,j}(\theta)/\hat\sigma_{n,j}(\theta)-1$. Then, (i) for each $j=1,\dots,J_1+J_2$
\begin{align}
	\inf_{P\in\mathcal P}P
	\Big(\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|
	\to 0\Big)=1.
\end{align}	
(ii)
For any $j=1,\dots,R_1$ 
let
\begin{align}
\hat \sigma_{n,j}^M(\theta)=\hat \sigma_{n,j+R_1}^M(\theta)\equiv\hat \mu_{n,j}(\theta)\hat\sigma_{n,j}(\theta)+(1-\hat \mu_{n,j}(\theta))\hat\sigma_{n,j+R_1}(\theta). 
\end{align} 
Let $(P_n,\theta_n)$ be a sequence such that $P_n\in\mathcal P$, $\theta_n\in\Theta$ for all $n$, and $\kappa_n^{-1}\sqrt{n}\gamma_{1,P_n,j}(\theta_n) \to \pi_{1j} \in \mathbb{R}_{[-\infty]}$. Let $\mathcal J^*$ be defined as in (H.29).
Then, for any $\eta>0$, there exists $N\in\mathbb N$ such that
\begin{align}
	P_n\Big(\max_{j\in(\mathcal R_1\cup \mathcal R_2)\cap\mathcal J^*}\Big|\frac{\sigma_{P_n,j}(\theta_n)}{\hat\sigma^M_{n,j}(\theta_n)}-1\Big|>\eta\Big)<\eta
\end{align}
for all  $n\ge N$.
